            AgentEvent::ToolCallItem {
                item: sample_item(),
            },
            AgentEvent::ToolOutputItem {
                item: sample_item(),
            },
            AgentEvent::HandoffItem {
                from: "a".to_owned(),
                to: "b".to_owned(),
            },
            AgentEvent::AgentUpdated {
                agent: "b".to_owned(),
